pub const AUX_CLICK_SCRIPT: &str = "node.scrollIntoView({block: 'center', inline: 'center'}); const rect = node.getBoundingClientRect(); const x = rect.left + rect.width / 2, y = rect.top + rect.height / 2; const top = document.elementFromPoint(x, y) || node; const button = __BUTTON__; const base = {bubbles: true, cancelable: true, composed: true, clientX: x, clientY: y, view: window, button}; const pointer = {pointerId: 1, pointerType: 'mouse', isPrimary: true}; top.dispatchEvent(new PointerEvent('pointerdown', {...base, ...pointer, buttons: 1 << button})); top.dispatchEvent(new MouseEvent('mousedown', {...base, buttons: 1 << button})); top.dispatchEvent(new PointerEvent('pointerup', {...base, ...pointer, buttons: 0})); top.dispatchEvent(new MouseEvent('mouseup', {...base, buttons: 0})); top.dispatchEvent(new MouseEvent(button === 2 ? 'contextmenu' : 'auxclick', {...base, buttons: 0})); return [Math.round(x), Math.round(y), top.localName];";
pub const DOUBLE_CLICK_SCRIPT: &str = "const rect = node.getBoundingClientRect(); const x = rect.left + rect.width / 2, y = rect.top + rect.height / 2; const top = document.elementFromPoint(x, y) || node; top.dispatchEvent(new MouseEvent('dblclick', {bubbles: true, cancelable: true, composed: true, clientX: x, clientY: y, view: window, button: 0, detail: 2})); return true;";
pub const DRAG_SCRIPT: &str = "const place = (node) => { node.scrollIntoView({block: 'center', inline: 'center'}); const rect = node.getBoundingClientRect(); return [rect.left + rect.width / 2, rect.top + rect.height / 2]; }; const [fromX, fromY] = place(source), [toX, toY] = place(target); const grab = document.elementFromPoint(fromX, fromY) || source; const steps = __STEPS__; const mouse = (type, node, x, y, buttons) => node.dispatchEvent(new MouseEvent(type, {bubbles: true, cancelable: true, composed: true, clientX: x, clientY: y, view: window, button: 0, buttons})); const pointer = (type, node, x, y, buttons) => node.dispatchEvent(new PointerEvent(type, {bubbles: true, cancelable: true, composed: true, clientX: x, clientY: y, view: window, button: 0, buttons, pointerId: 1, pointerType: 'mouse', isPrimary: true})); const transfer = new DataTransfer(); const draggable = grab.closest('[draggable=\"true\"]'); const drag = (type, node, x, y) => node.dispatchEvent(new DragEvent(type, {bubbles: true, cancelable: true, composed: true, clientX: x, clientY: y, view: window, dataTransfer: transfer})); pointer('pointerdown', grab, fromX, fromY, 1); mouse('mousedown', grab, fromX, fromY, 1); if (draggable) drag('dragstart', draggable, fromX, fromY); let over = grab; for (let step = 1; step <= steps; step++) { const x = fromX + (toX - fromX) * step / steps, y = fromY + (toY - fromY) * step / steps; over = document.elementFromPoint(x, y) || over; pointer('pointermove', over, x, y, 1); mouse('mousemove', over, x, y, 1); if (draggable) { drag('drag', draggable, x, y); drag('dragenter', over, x, y); drag('dragover', over, x, y); } } const end = document.elementFromPoint(toX, toY) || target; if (draggable) { drag('drop', end, toX, toY); drag('dragend', draggable, toX, toY); } pointer('pointerup', end, toX, toY, 0); mouse('mouseup', end, toX, toY, 0); return [Math.round(fromX), Math.round(fromY), Math.round(toX), Math.round(toY), Boolean(draggable)];";
pub const POINT_SCRIPT: &str = "((x, y, kind, count) => { const node = document.elementFromPoint(x, y) || document.body; const base = { bubbles: true, cancelable: true, composed: true, view: window, clientX: x, clientY: y, screenX: x, screenY: y, button: 0, buttons: 0, pointerId: 1, pointerType: 'mouse', isPrimary: true }; const pointer = (type, extra) => node.dispatchEvent(new PointerEvent(type, { ...base, ...extra })); const mouse = (type, extra) => node.dispatchEvent(new MouseEvent(type, { ...base, ...extra })); pointer('pointerover', {}); pointer('pointermove', {}); mouse('mouseover', {}); mouse('mousemove', {}); if (kind === 'click') { for (let i = 1; i <= count; i++) { pointer('pointerdown', { buttons: 1, detail: i }); mouse('mousedown', { buttons: 1, detail: i }); pointer('pointerup', { detail: i }); mouse('mouseup', { detail: i }); mouse('click', { detail: i }); } if (count === 2) mouse('dblclick', { detail: 2 }); } return node.tagName.toLowerCase() + (node.id ? '#' + node.id : ''); })(__X__, __Y__, __KIND__, __COUNT__)";
pub const FRAME_OFFSET_SCRIPT: &str = "((wanted, url) => { const frames = [...document.querySelectorAll('iframe,frame')]; const same = (frame) => { try { return new URL(frame.src, location.href).href === url; } catch (error) { return false; } }; const match = frames.find((frame) => frame.name === wanted || frame.id === wanted) || (url ? frames.find(same) : null) || frames.find((frame) => (frame.src || '').includes(wanted)); if (!match) return null; const rect = match.getBoundingClientRect(); return [rect.left + match.clientLeft, rect.top + match.clientTop]; })(__WANTED__, __URL__)";
pub const FRAME_LIST_SCRIPT: &str = "[...document.querySelectorAll('iframe,frame')].slice(0, 40).map((frame) => { const rect = frame.getBoundingClientRect(); let same = false; try { same = !!frame.contentWindow.document; } catch (error) {} return { name: frame.name || frame.id || '', src: frame.src || '', same_origin: same, box: [Math.round(rect.left), Math.round(rect.top), Math.round(rect.width), Math.round(rect.height)] }; })";
